import {recordsSummary} from './core/records.mjs';
import {recentSessions} from './host.mjs';
export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function recordsModel(row,keys,calendar){const all=[...row.history,...(row.current?[row.current]:[])];return {summary:recordsSummary(all,keys,calendar),visible:recentSessions(all.filter(s=>!row.hidden_ids.includes(s.session_id)))};}
export function focusMarkup({session:s,tasks,archived=[],setup,context={},showSetup=false,guide=false,reviewURL=null}){
 const esc=escapeHTML,active=s&&s.state!=='Ended',ended=s?.state==='Ended'&&!showSetup,selected=active||ended?s?.task_id:setup.task_id,task=tasks.find(t=>t.task_id===selected);
 const taskSelect=`<label class="mf-task-select">当前任务 <span class="tiny">可选</span><select id="mf-current-task"><option value="">暂不关联任务</option>${tasks.filter(t=>(!t.completed&&!archived.includes(t.task_id))||t.task_id===selected).map(t=>`<option value="${esc(t.task_id)}" ${t.task_id===selected?'selected':''}>${t.parent_id?'↳ ':''}${esc(t.title)}</option>`).join('')}</select></label>`;
 return `<section class="mf-focus-panel" aria-label="专注计时"><header class="mf-focus-heading"><p class="eyebrow">MIND FLOW</p><h1>${ended?'本次专注已保存':'专注'}</h1>${context.topic_id?`<p class="mf-context">Topic ${esc(context.topic_id)}</p>`:''}</header>${!active&&!ended?`<div class="mf-setup">${taskSelect}<label>计时方式<select id="mf-mode"><option value="free" ${setup.mode==='free'?'selected':''}>自由计时</option><option value="pomodoro" ${setup.mode==='pomodoro'?'selected':''}>定时模式</option></select></label><div class="mf-timed-settings" data-timed-settings ${setup.mode==='free'?'hidden':''}><label>专注分钟<input id="mf-focus-min" type="number" value="${setup.focus_min}" min="1" max="1440" required></label><label>休息分钟<input id="mf-rest-min" type="number" value="${setup.rest_min}" min="1" max="1440" required></label></div></div>`:`<div class="mf-current-title">${task?`<details class="mf-task-title-wrap"><summary class="mf-task-title" data-user-content>${esc(task.title)}</summary></details>`:'<p class="mf-task-title">自由学习</p>'}${active?`<details class="mf-switch-task"><summary>切换任务</summary>${taskSelect}</details>`:''}</div>`}<p class="mf-mode-caption" data-mode-caption>${ended?'本次专注时间':active&&s.phase_kind==='rest'?'休息 · 倒计时':(active?s.mode:setup.mode)==='free'?'自由计时 · 正计时':'定时模式 · 倒计时'}</p><div class="mf-clock"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="48"/><circle data-ring cx="50" cy="50" r="48" stroke-dasharray="301.593" stroke-dashoffset="301.593"/></svg><strong data-mf-clock>00:00</strong></div><p class="mf-state" data-mf-state></p><div class="mf-controls mf-primary-controls">${ended?'<button class="btn accent" data-mf="new-session">再次专注</button>':!active?'<button class="btn accent" data-mf="start">开始专注</button>':`${['Focusing','Resting'].includes(s.state)?'<button class="btn accent" data-mf="pause">暂停</button>':'<button class="btn accent" data-mf="resume">继续专注</button>'}<button class="btn secondary" data-mf="end">结束</button>`}</div><p class="tiny" data-mf-totals></p><p class="mf-recovery" data-mf-notice></p>${ended?`<div class="mf-next"><span class="tiny">${task?(task.completed?'任务已完成':'任务尚未标记完成'):'未关联任务'}</span>${task&&!task.completed?`<button class="ghost-btn" data-task-done="${esc(task.task_id)}">标记任务完成</button>`:''}<a class="ghost-btn" href="#mindflow/records">查看记录</a>${reviewURL?`<a class="ghost-btn" href="${esc(reviewURL)}">回忆与修正</a>`:''}</div>`:`<div class="mf-focus-tools">${active?'<button class="ghost-btn" data-mf="blocker">记录问题</button>':''}<details class="mf-more"><summary>更多</summary><div>${s?.state==='Focusing'?'<button class="ghost-btn" data-mf="rest">开始休息</button>':''}<button class="ghost-btn" data-mf="immerse">沉浸模式</button><button class="ghost-btn" data-mf="help">使用帮助</button>${reviewURL?`<a class="ghost-btn" href="${esc(reviewURL)}">回忆与修正</a>`:''}</div></details><button class="ghost-btn mf-exit" data-mf="exit">退出沉浸</button></div>`}${guide&&!active&&!ended?'<p class="mf-first-guide">选好计时方式即可开始，任务可以稍后再加。<button class="ghost-btn" data-mf="dismiss-guide">知道了</button></p>':''}</section>`;
}
